/* ============================================================================
   MSG-01 · Pantalla Lista de Hilos
   ============================================================================
   Sustituciones de token frente al HTML aprobado (F-003):
   - El mock usa blanco puro para el input, las tarjetas y los botones de
     paginación. El sistema de diseño no define token de blanco, así que se usa
     la superficie sutil más cercana (`--bw-surface-mist`).
   - El texto sobre el azul de acción era blanco puro; se usa `--bw-on-dark-hover`
     (el blanco translúcido que ya usa el shell sobre fondo oscuro).
   ========================================================================== */

.screen {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.pageTitle {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.pageSub {
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  margin-bottom: 16px;
  max-width: 560px;
}

.e2eeBar {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  padding: 6px 10px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  background: var(--bw-badge-success-bg);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-signal-green);
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.btnPrimary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-on-dark-hover);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: opacity 0.12s;
}

.btnPrimary:hover:not(:disabled) {
  opacity: 0.88;
}

.btnPrimary:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.threadCount {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.messageBox {
  padding: 48px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  font-size: 14px;
  color: var(--bw-text-secondary);
  text-align: center;
}

.errorBox {
  padding: 16px 20px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 8px;
  background: var(--bw-sensitive-bg);
  font-size: 14px;
  color: var(--bw-error-text);
  text-align: center;
}

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 56px 24px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-surface-mist);
  text-align: center;
}

.emptyText {
  max-width: 440px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: all 0.12s;
}

.pageBtn:hover:not(:disabled):not(.pageActive) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: not-allowed;
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
  cursor: default;
}

