import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA PANTALLA, no un componente de presentación: carga la página de hilos de
 * la organización (`fetchThreadPage`) y posee el estado de búsqueda y de página.
 * El orden de las filas lo decide el servidor (`last_item_at` descendente); esta
 * pantalla solo lo muestra.
 *
 * Lo que el mock promete y el MVP no tiene (F-023 / F-027):
 * - El aviso brass con botón «Introducir frase de seguridad» no se pinta: en el
 *   MVP no hay passphrase, backup ni recuperación (Plan §9 «Fuera»).
 * - «Nuevo contacto» e «Ir al Directorio» llevan a DIR-01, fuera de las ocho
 *   pantallas del alcance: se pintan deshabilitados con el motivo.
 * - No hay seguimiento de lectura en el esquema (ni read_at ni recibos), así que
 *   no hay punto azul ni recuento de no leídos. No se inventa un número.
 */

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj del sistema. */
  now?: Date;
  /**
   * MSG-02 no existía cuando se escribió esta tarea y abrir un hilo no lleva a
   * ningún sitio. El shell la pasa desde `App.tsx` porque la firma pública del
   * componente la exige (F-118, congelado por el PO el 28-ago-2026); se recibe
   * y se ignora a propósito.
   */
  onOpenThread?: (threadId: string) => void;
}

export function Messages({ profile, now, onOpenThread }: MessagesProps) {
  // Firmado por contrato público; abrir un hilo no navega a ningún sitio (MSG-02 no existe).
  void onOpenThread;

  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function loadPage() {
      setLoading(true);
      try {
        const data = await fetchThreadPage({ orgId: profile.orgId, search: searchTerm, page });
        if (cancelled) return;
        setThreads(data.threads);
        setTotal(data.total);
        setFailed(false);
      } catch {
        if (cancelled) return;
        setThreads([]);
        setTotal(0);
        setFailed(true);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    void loadPage();
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, searchTerm, page]);

  const commitSearch = () => {
    setSearchTerm(searchInput.trim());
    setPage(1);
  };

  const pages = pageCount(total);
  const pageNumbers = Array.from({ length: pages }, (_, i) => i + 1);

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.e2eeBar} role="status">
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={searchInput}
            onChange={(event) => setSearchInput(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') commitSearch();
            }}
          />
        </div>
        <button
          type="button"
          className={styles.btnPrimary}
          disabled
          title="El Directorio de Organizaciones no está disponible en esta versión"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.threadCount}>
          {total.toLocaleString('es-ES')} {total === 1 ? 'hilo' : 'hilos'} · Página{' '}
          {page.toLocaleString('es-ES')} de {pages.toLocaleString('es-ES')}
        </span>
      </div>

      {failed ? (
        <div className={styles.errorBox} role="alert">
          No se pudieron cargar los hilos. Inténtalo de nuevo en un momento.
        </div>
      ) : threads.length === 0 ? (
        loading ? (
          <div className={styles.messageBox}>Cargando hilos…</div>
        ) : searchTerm !== '' ? (
          <div className={styles.messageBox}>
            No se encontraron hilos que coincidan con «{searchTerm}».
          </div>
        ) : (
          <div className={styles.emptyState}>
            <p className={styles.emptyText}>
              Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
            </p>
            <button
              type="button"
              className={styles.btnPrimary}
              disabled
              title="El Directorio de Organizaciones no está disponible en esta versión"
            >
              <i className="ti ti-building" aria-hidden="true" />
              Ir al Directorio
            </button>
          </div>
        )
      ) : (
        <>
          <ThreadList
            threads={threads}
            now={now}
            // MSG-02 no existe: abrir un hilo no lleva a ningún sitio. `onOpenThread`
            // llega del shell pero se ignora a propósito (ver cabecera de este fichero).
            onOpen={() => {}}
          />
          {pages > 1 ? (
            <div className={styles.pagination}>
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page <= 1}
                aria-label="Página anterior"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
              >
                ‹
              </button>
              {pageNumbers.map((n) => (
                <button
                  key={n}
                  type="button"
                  className={`${styles.pageBtn} ${n === page ? styles.pageActive : ''}`}
                  aria-label={`Página ${n}`}
                  aria-current={n === page ? 'page' : undefined}
                  onClick={() => setPage(n)}
                >
                  {n}
                </button>
              ))}
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page >= pages}
                aria-label="Página siguiente"
                onClick={() => setPage((p) => Math.min(pages, p + 1))}
              >
                ›
              </button>
            </div>
          ) : null}
        </>
      )}
    </div>
  );
}

