/* ============================================================================
   MSG-01 · Lista de Hilos (componente de presentación)
   ============================================================================
   Sustituciones de token frente al HTML aprobado (F-003):
   - El mock usa blanco puro para la tarjeta de la lista; no hay token de
     blanco, se usa `--bw-surface-mist`, la superficie sutil más cercana.
   - El borde del badge «CON CONSULTA PENDIENTE» era un azul al 20 %; el token
     azul de borde más cercano es `--bw-chip-active-border` (30 %).
   ========================================================================== */

.list {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--bw-divider-mist);
  cursor: pointer;
  transition: background 0.1s;
}

.row:last-child {
  border-bottom: none;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.row:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.tsRow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.timestamp {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-text-secondary);
}

.stateBadge {
  flex-shrink: 0;
  padding: 2px 7px;
  border: 1px solid;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.badgeInfo {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.badgeWarn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.badgeSuccess {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.badgeClosed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

