import type { KeyboardEvent } from 'react';
import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01.
 *
 * Componente de presentación: pinta las filas en el orden en que las recibe (el
 * orden lo decide el servidor, `last_item_at` descendente) y avisa con el ID
 * del hilo cuando el usuario abre una. No carga datos ni pagina.
 *
 * Notas de diseño:
 * - La vista previa es metadato (tipo de elemento y referencia), nunca contenido
 *   descifrado (spec §7 / F-027).
 * - No hay punto azul ni recuento de no leídos: el esquema no tiene seguimiento
 *   de lectura y no se inventa un número delante del socio (F-023 / F-027).
 */

const TONE_CLASS: Record<StateTone, string> = {
  neutral: styles.badgeNeutral,
  info: styles.badgeInfo,
  warn: styles.badgeWarn,
  success: styles.badgeSuccess,
  closed: styles.badgeClosed,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj del sistema. */
  now?: Date;
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  return (
    <div className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            onOpen(thread.id);
          }
        };

        return (
          <div
            key={thread.id}
            role="button"
            tabIndex={0}
            className={styles.row}
            aria-label={`Abrir hilo con ${thread.counterpartyName}`}
            onClick={() => onOpen(thread.id)}
            onKeyDown={handleKeyDown}
          >
            <div className={styles.rowTop}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry !== '' ? (
                <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
              ) : null}
            </div>
            <div className={styles.tsRow}>
              <span className={styles.timestamp}>{relativeTime(thread.lastItemAt, now)}</span>
            </div>
            <div className={styles.rowBottom}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLASS[tone]}`}>{thread.state}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}
